def enable_trigram_search(apps, schema_editor):
    """Typo-tolerant knowledge search uses PostgreSQL's pg_trgm when it is
    available. Creating an extension needs privileges some managed databases
    don't grant, so a failure is not an error: retrieval then falls back to
    keyword matching (see bot_engine/knowledge.py)."""
    if schema_editor.connection.vendor != 'postgresql':
        return
    from django.db import transaction
    try:
        with transaction.atomic(using=schema_editor.connection.alias):
            schema_editor.execute('CREATE EXTENSION IF NOT EXISTS pg_trgm')
    except Exception:  # noqa: BLE001
        pass


